page+='''<script>
const videos=[...document.querySelectorAll('.comparison')];const scrub=document.querySelector('#scrub'),clock=document.querySelector('#clock');let seeking=false;
document.querySelector('#play-all').onclick=()=>Promise.all(videos.map(v=>v.play().catch(()=>{})));document.querySelector('#pause-all').onclick=()=>videos.forEach(v=>v.pause());document.querySelector('#reset-all').onclick=()=>{videos.forEach(v=>{v.pause();v.currentTime=0});scrub.value=0;clock.textContent='0.00 s'};
scrub.oninput=()=>{seeking=true;videos.forEach(v=>{v.pause();v.currentTime=+scrub.value});clock.textContent=(+scrub.value).toFixed(2)+' s';seeking=false};setInterval(()=>{if(!seeking&&!videos[0].paused){let t=videos[0].currentTime;scrub.value=t;clock.textContent=t.toFixed(2)+' s';videos.slice(1).forEach(v=>{if(Math.abs(v.currentTime-t)>.15)v.currentTime=t})}},100);
document.querySelector('#license-filter').onchange=e=>document.querySelectorAll('#licenses tbody tr').forEach(r=>r.hidden=e.target.value!=='all'&&r.dataset.kind!==e.target.value);
function cost(){let n=+document.querySelector('#requests').value;document.querySelector('#request-count').textContent=n.toLocaleString();let neurons=n*(3000*4625/1e6+600*30475/1e6);let net=Math.max(0,neurons-10000)*.011/1000;document.querySelector('#cost-result').textContent='$'+net.toFixed(3)+' / 일';}document.querySelector('#requests').oninput=cost;cost();
</script></html>'''
